insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('rule-stitch','apparel.vintage','rule','','ตะเข็บเดี่ยว vs ตะเข็บคู่','ก่อนปลายยุค 90',ARRAY['single stitch','ตะเข็บเดี่ยว','double stitch']::text[],'["ตะเข็บเดี่ยวที่ปลายแขนและชายเสื้อ = เสื้อวินเทจโดยทั่วไป", "ตะเข็บคู่สองแถว = มักผลิตหลังปลายยุค 90"]'::jsonb,'["ข้อยกเว้น: เสื้อทัวร์ยุโรปปลายยุค 90 บางตัวใช้ตะเข็บคู่ ใช้ประกอบกับป้ายเสมอ"]'::jsonb,'','sourced','["https://nostos.pages.dev/guides/vintage-band-tee-reprint-and-bootleg-identification-guide"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('rule-print','apparel.vintage','rule','','ดูลายสกรีน: ของเก่าจริง vs พิมพ์ใหม่','',ARRAY['print','สกรีน','dtg','heat transfer']::text[],'["สกรีนยุคเก่า: หมึกแตก ซีด ซึมลงเนื้อผ้า จับแล้วนุ่ม", "พิมพ์ DTG สมัยใหม่: หมึกหนา ยาง มันวาว ลอยบนผ้า", "ลายรีดร้อน (heat transfer) ยุค 1993–2000 เป็นของจริงแต่ราคาต่ำกว่าสกรีน: ขอบคม ผิวคล้ายพลาสติก ด้านในไม่มีหมึกซึม"]'::jsonb,'["ผ้าซีดเก่าแต่ลายสดใหม่ = อาจพิมพ์ใหม่บนเสื้อเก่า"]'::jsonb,'','sourced','["https://nostos.pages.dev/guides/vintage-band-tee-reprint-and-bootleg-identification-guide"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('rule-fake-aging','apparel.vintage','rule','','ทำเก่าปลอม vs เก่าจริง','',ARRAY['distressed','ฟอก','ทำเก่า']::text[],'["เก่าจริง: ซีดแดดตามธรรมชาติ รูเข็มเล็กๆ แถวคอ/เอว คอนิ่มและลุ่ย"]'::jsonb,'["ฟอกเคมีเป็นด่างไม่เป็นธรรมชาติ", "รูที่ตัดด้วยกรรไกร", "คอที่ขัดกระดาษทราย", "ตัดป้ายออกจนเป็นรูเละ หรือเป็นป้ายฉีกแบบกระดาษสมัยใหม่"]'::jsonb,'','sourced','["https://nostos.pages.dev/guides/vintage-band-tee-reprint-and-bootleg-identification-guide"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('rule-weak-signals','apparel.vintage','rule','','สัญญาณที่ใช้ตัดสินยุคอย่างเดียวไม่ได้','',ARRAY['made in usa','50/50','double tag']::text[],'["Made in USA, ผ้า 50/50, ป้ายซ้อนสองชั้น พบได้หลายแบรนด์หลายยุค ต้องใช้ร่วมกับรูปแบบป้ายและตะเข็บ", "ช่วงปีของแต่ละแบรนด์ทับซ้อนกัน ใช้ช่วงปีอย่างเดียวระบุแบรนด์ไม่ได้"]'::jsonb,'[]'::jsonb,'','sourced','["https://defunkd.com/vintage-t-shirt-tag-dating-guide"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('rule-copyright','apparel.vintage','rule','','ปีลิขสิทธิ์ (©) บนลายสกรีน','',ARRAY['©','copyright','ลิขสิทธิ์']::text[],'["ปี © คือปีที่ลายได้ลิขสิทธิ์ ไม่ใช่ปีที่พิมพ์เสื้อ และไม่ค่อยถูกอัปเดต เสื้อพิมพ์ยุค 2000 อาจยังเขียน © 1994", "มีหลายปี: ปีแรกคือลิขสิทธิ์เดิม ปีหลังคือแก้ไข เสื้อมักผลิตหลังปีล่าสุด (เช่น Snoopy 1958/1965/1971 น่าจะผลิตยุค 80 ขึ้นไป)", "ตัวอย่าง: Metallica Ride the Lightning ที่พิมพ์ยุค 2000 มักมี © 1994", "เสื้อวงที่พิมพ์ยุค 2000 หลายตัวไม่มีบรรทัด © เลย"]'::jsonb,'["ไม่มี © ไม่ได้แปลว่าปลอม (bootleg เก่าหลายตัวไม่มี)", "มี © ก็ไม่ได้แปลว่าแท้ เพราะ bootleg ก็ลอก © ได้", "ใช้ปี © ตัดสินยุคอย่างเดียวไม่ได้ ต้องดูป้ายและงานพิมพ์ประกอบ"]'::jsonb,'','sourced','["https://www.defunkd.com/copyrights-on-vintage-t-shirts/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('rule-rn','apparel.vintage','rule','','เลข RN บนป้าย','',ARRAY['rn','rn number','wpl']::text[],'["RN คือเลขที่ FTC สหรัฐฯ ออกให้ผู้ผลิต/ผู้นำเข้า ใช้ค้นว่าใครผลิต", "Screen Stars ใช้ RN 13765"]'::jsonb,'["RN หรือ WPL สมัยใหม่บนป้ายที่อ้างว่าเก่า = สัญญาณป้ายปลอม"]'::jsonb,'','sourced','["https://1800vintage.substack.com/p/rn-numbers", "https://www.defunkd.com/blog/2016/12/06/the-screen-stars-timeline/amp/", "https://www.defunkd.com/fake-tag-archive/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('rule-fake-tag','apparel.vintage','rule','','สัญญาณป้ายคอปลอม (ทั่วไป)','',ARRAY['fake tag','ป้ายปลอม']::text[],'["เทียบกับป้ายแท้หลายๆ ใบ เพราะป้ายแท้เองก็มีหลายแบบ", "ดูทั้งป้ายและลายสกรีนประกอบกัน"]'::jsonb,'["โลโก้หนาทึบ เส้นด้ายหยาบ จุดลายหายไป", "ฟอนต์ ความสูงตัวอักษร ระยะห่างผิด", "สะกดผิด", "ขาดรายละเอียด เงา ขอบ หรือความแวววาว", "สีผิด", "ไซซ์บนป้ายไม่ตรงกับขนาดจริง", "ป้ายรอง/เลข RN-WPL ไม่ตรงยุค", "ตำแหน่ง ™ ผิด"]'::jsonb,'','sourced','["https://www.defunkd.com/fake-tag-archive/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('tag-screen-stars','apparel.vintage','tag','Screen Stars','Screen Stars','1980–1994',ARRAY['screen stars','screenstars','super screen stars','screen stars best']::text[],'["1980: ป้ายแรก สีน้ำเงิน/ขาว/ส้ม ใช้ปีเดียว ส่วนใหญ่ 50/50", "1981–1983: ตัว A แบบ \"Funky A\" (แบบที่ดังที่สุด), Super Screen Stars แถบเขียว 50/50, แถบน้ำเงิน 100% cotton", "1983–1990: ตัว A แบบเรียบขึ้น, มีรุ่น Made in Canada / Ireland / El Salvador", "1987–90s: Screen Stars Best แถบแดง 50/50 และแถบน้ำเงิน 100% cotton", "RN 13765 (เครือ Fruit of the Loom)"]'::jsonb,'["ป้าย \"Screen Stars by FOTL Value Weight\" ปลอม: น้ำเงินเข้มเกิน กล่องสี่เหลี่ยมจัตุรัส ฟอนต์ \"by\" ผิด"]'::jsonb,'ป้ายที่นักสะสมรู้จักดี เสื้อลายดีบนป้ายนี้มักขายได้ราคา','sourced','["https://www.defunkd.com/blog/2016/12/06/the-screen-stars-timeline/amp/", "https://defunkd.com/vintage-t-shirt-tag-dating-guide", "https://www.defunkd.com/fake-tag-archive/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('tag-fotl','apparel.vintage','tag','Fruit of the Loom','Fruit of the Loom','1970–1998 (ป้ายวินเทจ)',ARRAY['fruit of the loom','fotl','fruit']::text[],'["มีรูปแบบป้ายแยกช่วง 1970s–1983 และ 1984–1993", "มีรุ่น \"Best\" และ Lofteez/heavy cotton แบบป้ายซ้อน", "ป้ายยุค 2004–2012 ไม่นับเป็นวินเทจยุคทอง"]'::jsonb,'["ป้ายปลอม: ไม่มีรายละเอียดและเงาของผลไม้ และองุ่นเป็นสีม่วง"]'::jsonb,'','sourced','["https://defunkd.com/vintage-t-shirt-tag-dating-guide", "https://www.defunkd.com/fake-tag-archive/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
