insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('genre-band','apparel.vintage','genre','','เสื้อวงดนตรี (Band tee)','',ARRAY['band','tour','เสื้อวง','metallica','nirvana','rolling stones','u2','grateful dead','guns n roses','iron maiden','concert']::text[],'["3 ระดับ: เสื้อทัวร์ทางการ (ราคาสูงสุด) > bootleg ยุคเก่าที่ขายหน้าคอนเสิร์ต (ก็มีมูลค่า) > ของปลอม/พิมพ์ใหม่", "เสื้อทางการ: มีป้ายลิขสิทธิ์ บรรทัด © และป้ายตรงยุค", "Bootleg ยุคเก่า: ลายใหญ่ ไม่มีป้ายลิขสิทธิ์ แต่ตัวเสื้อและป้ายเปล่าเก่าจริง", "วงที่นักสะสมตามหามาก: Nirvana (In Utero), Metallica (Ride the Lightning) และวงกรันจ์/เมทัลยุค 90", "ดูวันทัวร์ด้านหลังเทียบกับยุคป้าย"]'::jsonb,'["ลายเบลอแตกพิกเซล โลโก้ถูกตัด/บิด พิมพ์เบี้ยว", "ป้ายลิขสิทธิ์ไม่มีหรือดูไม่เป็นทางการ (สำหรับเสื้อที่อ้างว่าเป็นของทางการ)", "ราคาถูกผิดปกติ"]'::jsonb,'หมวดราคาสูงสุดของเสื้อยืดวินเทจ จึงเป็นหมวดที่ถูกปลอมมากที่สุด','sourced','["https://nostos.pages.dev/guides/vintage-band-tee-reprint-and-bootleg-identification-guide", "https://rockabilia.com/pages/official-vs-bootleg-band-merchandise"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('genre-harley','apparel.vintage','genre','','Harley-Davidson','',ARRAY['harley','harley-davidson','harley davidson','motor clothes','sturgis','laconia']::text[],'["ยุค 60–70: มักไม่มีป้ายเฉพาะ ใช้เสื้อเปล่า Hanes/Screen Stars/Champion", "ยุค 80: ป้าย Harley สีดำโลโก้ bar & shield ส้มขาว บางตัวใช้ป้าย 3D Emblem", "ยุค 90: ป้ายทอเรียบร้อยขึ้น บางตัวเขียน Harley-Davidson Motor Clothes", "ด้านหลังมักพิมพ์ชื่อดีลเลอร์/เมือง (นิยมในยุค 80)", "Made in USA ยุค 80–90 มักเป็นตะเข็บเดี่ยว; ผลิตในสหรัฐฯ ส่วนใหญ่หยุดราว 2010"]'::jsonb,'["ป้าย \"Harley Clothes\" ปลอม: ฟอนต์ HARLEY สูงผอมเกิน ระยะรอบ \"Clothes\" ผิด"]'::jsonb,'ลายดีลเลอร์เฉพาะพื้นที่ยุค 80 และเสื้องานแรลลี่ (Sturgis, Laconia) นักสะสมนิยม','sourced','["https://www.vintagerareusa.com/blogs/news/vintage-harley-davidson-3d-emblem-tee-shirt-label-history-since-1960s-vintage-rare-usa", "https://www.defunkd.com/fake-tag-archive/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('genre-nike','apparel.vintage','brand','','Nike (ป้ายเสื้อผ้า)','',ARRAY['nike','swoosh']::text[],'["Pinwheel 1978–1982", "ป้ายส้ม 1978–1983", "ป้ายน้ำเงิน 1984–1987", "ป้ายเทา ราว 1987–1994", "ป้ายดำ ราว 1994", "ป้ายขาว 1994–1999", "ป้ายแดงดำ 1997–1999", "ป้ายเงิน ต้น-กลางยุค 2000"]'::jsonb,'["ป้ายบอกช่วงเวลา ไม่ใช่ปีเป๊ะ และช่วงทับซ้อนกันได้", "ผลิตนอกสหรัฐฯ ไม่ได้แปลว่าปลอมหรือใหม่เสมอไป"]'::jsonb,'','sourced','["https://www.vintagerareusa.com/blogs/news/how-to-date-my-vintage-nike-with-the-tags-vintage-rare-usa"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('genre-champion','apparel.vintage','brand','','Champion Reverse Weave','',ARRAY['champion','reverse weave']::text[],'["ยุค 50–60: ป้ายแรกที่มีคำว่า Reverse Weave", "ปลาย 60–70: ป้ายหลายสี (น้ำเงิน เหลือง แดง เขียว ดำ) Made in USA", "ยุค 80: Made in USA ผ้า 90% cotton/10% acrylic หรือ 89/8/3 (cotton/acrylic/rayon)", "ยุค 90: ส่วนใหญ่ USA บางส่วนเม็กซิโก", "ปลาย 90–2000: ย้ายไปเม็กซิโก/เอลซัลวาดอร์"]'::jsonb,'[]'::jsonb,'สเวตเตอร์ Reverse Weave Made in USA เป็นที่ต้องการ','sourced','["https://www.vintagerareusa.com/blogs/news/champion-reverse-weave-label-history-per-year"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
