insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('genre-cartoon-movie','apparel.vintage','genre','','เสื้อการ์ตูน/คอมิก/หนัง','',ARRAY['disney','mickey','looney','simpsons','marvel','spider-man','spiderman','star wars','pulp fiction','matrix','movie','การ์ตูน','หนัง']::text[],'["ลิขสิทธิ์ทางการมีบรรทัด © ของเจ้าของลิขสิทธิ์", "Marvel ยุค 90 เป็นที่ต้องการ: เสื้อ Spider-Man/Daredevil/Silver Surfer ปี 1997 เคยขายออนไลน์ได้ 220,000 บาท", "เสื้อโปรโมตหนังยุคแรก (Star Wars, Pulp Fiction, The Matrix) หลายรุ่นไม่ได้ผลิตขายทั่วไป นักสะสมตามหา"]'::jsonb,'["ลายการ์ตูนดังถูกพิมพ์ซ้ำเยอะ เช็คป้ายกับยุคของลายเสมอ"]'::jsonb,'ตัวที่ราคาสูงคือลายหายากและของเก่าจริง ลายทั่วไปราคาระดับกลาง','sourced','["https://www.benarnews.org/english/news/thai/secondhand-clothes-boom-deep-south-02142025113206.html", "https://esquire.co.th/2026/07/30/vintage-t-shirts-value-michael-b-jordan"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('genre-anime','apparel.vintage','genre','','เสื้ออนิเมะยุค 90 (Akira, Dragon Ball ฯลฯ)','',ARRAY['akira','dragon ball','dbz','ghost in the shell','anime','อนิเมะ','manga']::text[],'["Akira ถูกยกเป็นตัวท็อป ลายต้นฉบับปี 1988 มีรายงานราคาประมูลเกิน $3,000", "Dragon Ball Z ยุค 90 โดยเฉพาะลายพิมพ์รอบตัว (AOP), Ghost in the Shell", "ป้ายต้องเข้ากับยุคของลาย: ลาย Akira 1988 บนป้ายยุค 2010 = พิมพ์ใหม่", "ตะเข็บเดี่ยว, สกรีนซึมเนื้อผ้า, © พิมพ์ลงเนื้อผ้า ไม่ลอยบนผิว"]'::jsonb,'["ซีดด้วยน้ำยาฟอกขาวเลียนแบบความเก่า", "ลายพิมพ์ดิจิทัล/รีดร้อนที่ผิวเป็นพลาสติก"]'::jsonb,'ตัวเลขราคามาจากร้านขาย ยังไม่มีแหล่งอื่นยืนยัน ใช้เป็นแนวทางเท่านั้น','general','["https://www.yiume.com/es/pages/faq-why-vintage-anime-shirts-expensive-2026"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('band-value','apparel.vintage','genre','','เสื้อวงที่ราคาสูง (ข้อมูลขายจริง)','',ARRAY['nirvana','grateful dead','bjork','björk','soundgarden','metallica','red hot chili peppers','rhcp','guns n roses','guns n'' roses','green day','pearl jam','earth wind','oasis','pushead']::text[],'["ผลศึกษาราคาขายต่อ (ธ.ค. 2023–ก.ย. 2024): Grateful Dead \"Panther\" สูงสุด $2,750, Nirvana In Utero แขนยาว $2,000, Björk Post (1995), Soundgarden Louder Than Love (1989), Metallica Load (1996), Nirvana Sliver tour (1992)", "วงที่ราคาเฉลี่ยต่อตัวสูง: Nirvana, Red Hot Chili Peppers, Earth Wind & Fire, Guns N'' Roses, Green Day, Paul McCartney, Pearl Jam", "ยุคที่ราคาดีที่สุด: ปลายยุค 80 ถึงกลางยุค 90 แนวร็อกราคาเฉลี่ยสูงกว่าป๊อปและแร็ป", "Grateful Dead ลาย Dancing Bears/Skeleton และ Metallica ลายของ Pushead เป็นที่ตามหา", "Oasis ยุค 90 ความต้องการเพิ่มขึ้นหลังประกาศรียูเนียนปี 2025"]'::jsonb,'["ราคาประเมินกับราคาซื้อขายจริงต่างกันได้มาก (เช่น เสื้อ Nirvana staff ปี 1991 ที่มีข่าวประเมิน 1.35 ล้านบาท แต่เจ้าของซื้อมาหลักหมื่น)", "วงดังที่สุดคือวงที่มีของพิมพ์ใหม่มากที่สุด"]'::jsonb,'เสื้อทัวร์ทางการ/ลายอัลบั้มเฉพาะ และเสื้อทีมงานที่ผลิตน้อย ราคาสูงสุด','sourced','["https://loudwire.com/study-bands-most-valuable-vintage-t-shirts/", "https://esquire.co.th/2026/07/30/vintage-t-shirts-value-michael-b-jordan", "https://marketeeronline.co/archives/429691"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('market-thai-bale','apparel.vintage','market','','ตลาดเสื้อมือสองกระสอบในไทย','',ARRAY['กระสอบ','bale','มือสอง','โรงเกลือ','ยะลา','ปัตตานี']::text[],'["เสื้อมือสองส่วนใหญ่มาจากสหรัฐฯ ส่งเรือไปมาเลเซียแล้วเข้าไทย", "ตัวอย่างจากภาคใต้: กระสอบละราว 1,000 บาท มีเสื้อยืด 200–220 ตัว หรือแจ็คเก็ต/กางเกง 150–180 ตัว", "ตลาดที่มีข่าว: ตลาดมะพร้าว (ยะลา), รูสะมิแล และยะหริ่ง (ปัตตานี)", "ของที่ขายได้ราคา: เสื้อยืดผลิตในสหรัฐฯ ผ้าบาง (นักสะสมญี่ปุ่นชอบ), เสื้อวงทั้งทางการและ bootleg, เสื้อทหารยุคสงคราม, ชุดทำงาน, ยีนส์, เสื้อกีฬา, เสื้อฮาวาย", "ตัวอย่าง: เสื้อยุค 70 ซื้อ 80 บาท ขายได้ 22,000 บาท"]'::jsonb,'[]'::jsonb,'กำไรมาจากการรู้ว่าตัวไหนมีค่า ใช้โหมดสแกนรัวคัดกอง','sourced','["https://www.benarnews.org/english/news/thai/secondhand-clothes-boom-deep-south-02142025113206.html"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('trend-now','apparel.vintage','trend','','กระแสตอนนี้ (อัปเดต พ.ย. 2026)','',ARRAY['trend','กระแส','blokecore','oasis','world cup']::text[],'["เสื้อกราฟิก/วินเทจกลับมาได้รับความสนใจในช่วง 2–3 ปีที่ผ่านมา เสื้อวงและเสื้อหนังนิยมสูง", "เสื้อบอลย้อนยุคมาแรงจากกระแส blokecore และฟุตบอลโลก 2026", "Oasis ยุค 90 ความต้องการเพิ่มหลังรียูเนียน", "เสื้ออนิเมะยุค 90 คนรุ่นใหม่สนใจ"]'::jsonb,'["กระแสเปลี่ยนเร็ว ควรอัปเดตหัวข้อนี้ทุก 2–3 เดือน"]'::jsonb,'','sourced','["https://esquire.co.th/2026/07/30/vintage-t-shirts-value-michael-b-jordan", "https://www.outlookindia.com/sports/football/fifa-world-cup-2026-hottest-jerseys-blokecore-retro-shirts-fashion-trends", "https://marketeeronline.co/archives/429691"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('levis-tab','apparel.denim','brand','','Levi''s: แท็บแดง (Big E / small e)','',ARRAY['levi''s','levis','levi','big e','red tab','แท็บแดง','บิ๊กอี']::text[],'["Big E (LEVI''S ตัว E ใหญ่) = ก่อนปี 1971", "small e (Levi''s ตัว e เล็ก) = ตั้งแต่ 1971", "แท็บพิมพ์ด้านเดียว = รุ่นเก่ามาก (ราวก่อนกลางยุค 50)", "ราว 10% ของการผลิตใช้แท็บเปล่า แท็บเปล่าจึงไม่ได้บอกยุค", "small e บางรุ่นก็หายากและมีราคา"]'::jsonb,'["Big E กลับมาใช้อีกตั้งแต่ 2018 บนสินค้าพรีเมียม", "LVC (Levi''s Vintage Clothing) และของปลอมอาจมีทั้ง Big E และป้ายวิธีซัก = ต้องดูป้ายวิธีซักและรายละเอียดอื่นประกอบ"]'::jsonb,'Big E ราคาสูงกว่ามาก','sourced','["https://www.thecollectorscompanion.co.uk/features/vintage-clothing/dating-levis/", "https://www.ropedye.com/2013/05/guide-how-to-date-levis-501-jeans/", "https://selvedgestory.pages.dev/en/guide/vintage-denim-authentication-guide/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('levis-construction','apparel.denim','rule','','Levi''s: หมุด ตะเข็บ ริม ป้ายหลัง','',ARRAY['levi''s','levis','501','selvedge','redline','ริมแดง','hidden rivet']::text[],'["หมุดซ่อนในกระเป๋าหลัง 1937–1966 จากนั้นเปลี่ยนเป็นบาร์แทค", "ป้ายหนัง Two Horse จนถึงราว 1955 จากนั้นเป็นป้ายกระดาษ (Jacron)", "ผ้าริม (selvedge/ริมแดง) ด้านในตะเข็บข้างขา = ราวก่อนกลางยุค 80", "ตะเข็บด้านนอกขาแบบโพ้งสีส้มราว 1981, โพ้งสีขาวราว 1985", "ตะเข็บด้านบนกระเป๋าหลังแบบเดี่ยว (lock stitch) ราวก่อน 1976 จากนั้นเป็นแบบโซ่", "หลังเอวรัด (cinch back) เลิกราว 1947"]'::jsonb,'["ซีดสม่ำเสมอผิดธรรมชาติหรือฟอกดูถูก = ระวัง", "ของ repro ญี่ปุ่นทำรายละเอียดได้เหมือนมาก ต้องดูหลายจุดประกอบ"]'::jsonb,'','sourced','["https://www.thecollectorscompanion.co.uk/features/vintage-clothing/dating-levis/", "https://www.ropedye.com/2013/05/guide-how-to-date-levis-501-jeans/", "https://selvedgestory.pages.dev/en/guide/vintage-denim-authentication-guide/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('levis-care','apparel.denim','rule','','Levi''s: อ่านป้ายวิธีซักและรหัสวันผลิต','',ARRAY['levi''s','levis','care tag','care label','ป้ายวิธีซัก']::text[],'["ไม่มีป้ายวิธีซักเลย = ก่อนราว 1971", "ราว 1968–1972: วิธีซักพิมพ์ในผ้ากระเป๋า", "1973–1983: ป้ายกระดาษเล็กข้างตะเข็บซ้าย มีวงกลมสีบอกรหัส", "ราว 1984 เป็นต้นไป: รหัส 3 หลัก เช่น 127 = ธันวาคม 1987", "1993 เป็นต้นไป: รหัส 4 หลัก เช่น 1295 = ธันวาคม 1995", "ป้ายรูป batwing ตั้งแต่ 1986/1987, คำว่า \"Care on Reverse\" = ก่อนราว 1992", "Made in USA สิ้นสุดราวปี 2003"]'::jsonb,'["ป้ายบอกปีล่าสุดแต่ดีไซน์อ้างว่าเก่า = รุ่น repro/LVC"]'::jsonb,'','sourced','["https://levis-vintage-id.vercel.app/en/articles/article-care-label", "https://www.thecollectorscompanion.co.uk/features/vintage-clothing/dating-levis/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('levis-jackets','apparel.denim','brand','','Levi''s: แจ็คเก็ตยีนส์ Type I / II / III','',ARRAY['jacket','trucker','506xx','507xx','557','70505','แจ็คเก็ต','type i','type ii','type iii']::text[],'["Type I (506XX): ก่อนยุค 40 กระเป๋าหน้าเดียวมีหมุดที่มุม หลังมีหัวเข็มขัดรัด (หายากสุด)", "Type II (507XX): ปลายยุค 40–60 กระเป๋าอกสองข้างมีฝาติดกระดุม ใช้บาร์แทคแทนหมุด", "Type III (557XX): 1962 ฝากระเป๋าแหลม (ทรง Trucker)", "ก่อน 1971: ตะเข็บแถวเดียวที่รังกระดุมล่าง; ตั้งแต่ 1971: ตะเข็บสองแถว + small e", "กลางยุค 80 ขึ้นไป: 4 กระเป๋า (อก 2 + ล้วงข้าง 2) นักสะสมสนใจน้อยกว่า"]'::jsonb,'[]'::jsonb,'ยิ่งเก่า (Big E, 2 กระเป๋า) ยิ่งแพง','sourced','["https://bragvintage.com/levis-denim-jacket-guide"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('lee','apparel.denim','brand','','Lee 101 / 101Z','',ARRAY['lee','101z','101j','storm rider','lazy s']::text[],'["ผ้า Left-Hand Twill (ลายทแยงกลับด้านกับ Levi''s)", "ตะเข็บกระเป๋าหลังรูป Lazy S (ปรับดีไซน์ราว 1944–1946)", "101Z ซิปหน้าเริ่มราว 1926–1927", "ป้ายเปลี่ยนจากหนังเป็นกระดาษใส"]'::jsonb,'[]'::jsonb,'','sourced','["https://selvedgestory.pages.dev/en/guide/vintage-denim-authentication-guide/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('wrangler','apparel.denim','brand','','Wrangler 13MWZ','',ARRAY['wrangler','13mwz','blue bell','11mwz']::text[],'["13MWZ เปิดตัว 1947", "ผ้าทวิลธรรมดา 1947–1963, ผ้า Broken Twill ตั้งแต่ 1964", "หมุดซ่อน ตะเข็บรูป W นูนที่กระเป๋าหลัง ซิปหน้า"]'::jsonb,'[]'::jsonb,'','sourced','["https://selvedgestory.pages.dev/en/guide/vintage-denim-authentication-guide/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('carhartt','apparel.denim','brand','','Carhartt','',ARRAY['carhartt','detroit jacket','j01','j97','chore coat','double knee']::text[],'["รหัสวันที่ในป้ายวิธีซัก อ่านเป็นเดือน-ปี เช่น 0698 = มิถุนายน 1998, ต้นยุค 90 อาจไม่มีศูนย์นำหน้า เช่น 591 = พฤษภาคม 1991", "ป้าย Union + Made in USA = ยุคก่อนย้ายฐานผลิต", "J01 Detroit: ผ้าดั๊กแข็ง 12oz ไซซ์เป็นตัวเลข (38–44) ปกลูกฟูก", "J97 Detroit: ปลายยุค 90 ไซซ์ตัวอักษร ผ้านุ่มกว่า"]'::jsonb,'["ซิปไม่มียี่ห้อเบาๆ (ของเก่ามักเป็น YKK หนัก หรือ Talon ทองเหลือง)", "ปักโลโก้ใหญ่หรือเบี้ยว", "ซับในฟลีซเทาสังเคราะห์ (ของเก่ามักเป็นซับผ้าห่มลายสก็อต)", "ทำเก่าด้วยเคมี"]'::jsonb,'Detroit Jacket และ Made in USA เป็นที่ต้องการ','sourced','["https://nostos.pages.dev/guides/identifying-vintage-carhartt-and-workwear"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('denim-general','apparel.denim','rule','','ยีนส์วินเทจ: ดูผ้าและการซีด','',ARRAY['denim','jeans','ยีนส์','rope dye']::text[],'["ยีนส์เก่าส่วนใหญ่ย้อมแบบ rope dye ซีดเป็นเส้นแนวตั้ง มีรอยรังผึ้งหลังเข่าและหนวดแมว", "ผ้ายีนส์วินเทจมักหนาราว 13–15oz"]'::jsonb,'["ซีดสม่ำเสมอผิดธรรมชาติ", "อย่าเชื่อป้าย \"Made in [ปี]\" หรือคำบรรยายของผู้ขายโดยไม่ตรวจเอง", "อย่าใช้ Big E อย่างเดียวตัดสิน"]'::jsonb,'','sourced','["https://selvedgestory.pages.dev/en/guide/vintage-denim-authentication-guide/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('fb-rule-check','apparel.football','rule','','เสื้อบอล: เช็คของแท้พื้นฐาน','',ARRAY['football','soccer','jersey','kit','เสื้อบอล','เสื้อฟุตบอล','product code']::text[],'["หารหัสสินค้าบนป้ายด้านใน แล้วค้นใน Google ต้องขึ้นเสื้อตัวเดียวกันเป๊ะ (ทีม ปี เหย้า/เยือน)", "ผู้ขายไม่ยอมโชว์ป้าย = สัญญาณเตือน, ป้ายถูกตัดออก = ซื้อเสี่ยงเอง", "เทียบสี ความคมของลาย และตำแหน่งดีไซน์กับรูปจากร้านทางการ"]'::jsonb,'["ป้ายเสื้อเก่ามีรอยปากกา/ดินสอเขียน", "เสื้อออกใหม่ลด 50% หรือของหายากราคาถูกผิดปกติ", "เสื้อก่อนปี 2000 มีครบทุกไซซ์ XS–XXL", "ประกาศใช้คำว่า \"replica\" หรือ \"retro\" (อาจเป็นงานทำใหม่หรือของปลอม)"]'::jsonb,'','sourced','["https://footballshirtcollective.com/blogs/collectors-club/spot-a-fake-shirt"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('fb-thai-grade','apparel.football','rule','','คำว่า "เกรดเอ / เกรดแฟนบอล / เกรดนักเตะ" ในไทย','',ARRAY['เกรดเอ','เกรด a','aaa','เกรดไทย','งานไทย','เกรดนักเตะ','เกรดแฟนบอล']::text[],'["ในไทยมีร้านขายเสื้อบอลที่ระบุว่า \"เกรดเอ/เกรดแฟนบอล/เกรดนักเตะ/เกรดพรีเมียม\" แยกจากของลิขสิทธิ์", "ของลิขสิทธิ์จริงก็มีรุ่นนักเตะ (Player/Authentic) กับรุ่นแฟน (Replica) แต่ต้องเช็ครหัสสินค้าได้"]'::jsonb,'["ผู้ขายเรียกว่า \"เกรด...\" แทนการบอกว่าลิขสิทธิ์แท้ = ให้ถือว่าไม่ใช่ของลิขสิทธิ์ อย่าซื้อในราคาของแท้ และอย่าขายต่อว่าเป็นของแท้"]'::jsonb,'','general','["https://www.welovefootballshop.com/product/tag/%E0%B9%80%E0%B8%AA%E0%B8%B7%E0%B9%89%E0%B8%AD%E0%B8%9F%E0%B8%B8%E0%B8%95%E0%B8%9A%E0%B8%AD%E0%B8%A5%E0%B8%AB%E0%B8%A5%E0%B8%B1%E0%B8%87%E0%B8%AA%E0%B8%99%E0%B8%B2%E0%B8%A1%E0%B8%A8%E0%B8%B8%E0%B8%A0?tskp=13"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('fb-player-fan','apparel.football','rule','','รุ่นนักเตะ (Player/Authentic) vs รุ่นแฟน (Replica)','',ARRAY['player issue','player version','authentic','replica','fan version','vaporknit','dri-fit adv','heat.rdy','aeroready','รุ่นนักเตะ','รุ่นแฟน']::text[],'["รุ่นนักเตะ: ทรงเข้ารูป ผ้าบางเบาระบายอากาศ โลโก้/ตราแบบรีดร้อน ใช้ Nike Dri-FIT ADV หรือ adidas HEAT.RDY", "รุ่นแฟน: ทรงปกติ ผ้าหนากว่า โลโก้/ตราแบบปัก ใช้ Nike Dri-FIT หรือ adidas AEROREADY", "ทั้งสองรุ่นเป็นของลิขสิทธิ์ คำว่า \"authentic\" หมายถึงรุ่นนักเตะ", "ราคาป้ายยุโรป: รุ่นนักเตะราว €140–160, รุ่นแฟนราว €90–110", "เสื้อยุคเก่า รุ่นนักเตะกับรุ่นแฟนแยกกันชัดเจนแค่ราว 10 ปีหลัง"]'::jsonb,'[]'::jsonb,'','sourced','["https://first11shirts.com/blogs/informative/player-vs-fan-version-football-shirts-what-s-the-difference", "https://themomentum.co/feature-football-jersey/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('fb-nike','apparel.football','brand','','Nike: เช็คเสื้อบอล','',ARRAY['nike','swoosh']::text[],'["รหัสสินค้า: ป้ายเล็กด้านในใกล้ชายเสื้อ รูปแบบ ตัวเลข 6 หลัก-3 หลัก (เช่น 123456-789) ค้นแล้วต้องขึ้นเสื้อตัวนั้นเป๊ะ", "Jock tag (ป้ายด้านหน้ามุมล่าง) มีรหัสยาวที่ไม่ซ้ำกันในแต่ละตัว", "เสื้อรุ่นใหม่มีป้ายที่ปลายแขน", "ขอบ swoosh คม"]'::jsonb,'["รหัสสินค้าขึ้นเป็นเสื้ออีกตัว (เช่น ชุดเหย้าแทนชุดเยือน)", "ไม่มีป้ายรหัสสินค้า", "รหัส jock tag ซ้ำกับเสื้อหลายตัว", "ปลาย swoosh ลากยาว งานปักเละ", "ด้านในหลัง swoosh/ตรามีวัสดุรองเกินมาก (สัญญาณคลาสสิก)", "ป้ายคอบนเสื้อรุ่นใหม่ (ไม่ได้ปลอมเสมอ แต่ต้องเช็คเพิ่ม)", "France 2016 ชุดเยือน เป็นรหัสที่ของปลอมใช้บ่อย"]'::jsonb,'','sourced','["https://footballshirtcollective.com/blogs/collectors-club/spot-fake-nike"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('fb-adidas','apparel.football','brand','','adidas: เช็คเสื้อบอล','',ARRAY['adidas','three stripes','trefoil']::text[],'["รหัสสินค้าที่ป้ายคอด้านใน: ตัวอักษร 2 ตัว + ตัวเลข 4 ตัว (เช่น DP2644) ค้นแล้วต้องตรงเสื้อ", "ป้ายคอของแท้มีตัวย่อชื่อสโมสร/ประเทศ", "โลโก้: ตัวหนังสือแตะขอบล่างของแถบ ระยะตัวอักษรสม่ำเสมอ แถบตรง", "jock tag มักอยู่มุมล่างด้านหน้า ไม่มีก็ไม่ได้แปลว่าปลอม (รุ่นแฟนบางรุ่นไม่มี)"]'::jsonb,'["ป้ายคอเขียนกว้างๆ ว่า \"ADIDAS JSY\"", "ป้ายคอติดกลับหัว", "ด้ายลากระหว่างตัวอักษร ฟอนต์บางเกิน แถบเบี้ยว ผ้าย่นรอบโลโก้", "ของหายากราคาถูก หรือมีครบทุกไซซ์"]'::jsonb,'','sourced','["https://footballshirtcollective.com/blogs/collectors-club/spot-fake-adidas"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('fb-umbro','apparel.football','brand','','Umbro ยุค 90','',ARRAY['umbro']::text[],'["ป้ายคอสีน้ำเงิน ตัวอักษร UMBRO มีจุดชัด", "บางตัวมีป้ายขาวบอกไซซ์/วิธีซักใต้ป้ายน้ำเงิน (ต้นยุค 90 มักไม่มี ปลายยุค 90 เกือบทุกตัวมี)", "ป้ายคอสีขาวตัวอักษรน้ำเงิน พบบ่อยในเสื้อ Celtic", "ช่วง 1998–2000 เปลี่ยนแบบป้าย อาจเจอทั้งสองแบบในเสื้อลายเดียวกัน"]'::jsonb,'["ไม่มีจุดในตัวอักษร UMBRO", "ป้ายแบนเรียบ เย็บน้อยกว่า (แต่ป้ายยุค 90 เย็บไม่สวยก็เป็นของแท้ได้)"]'::jsonb,'','sourced','["https://casualfootballshirts.co.uk/pages/1990s-umbro-shirts-authenticity-checks"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('fb-kappa','apparel.football','brand','','Kappa','',ARRAY['kappa','omini','kombat']::text[],'["รุ่นใหม่: ป้ายด้านในมีหมายเลข/QR ตรวจที่ BasicLabels.net", "ยุค 90: ป้ายหลักด้านในมีจุด 6 จุดเรียงสองแนวทแยง สม่ำเสมอ", "ของแท้มักมีป้ายด้านในมากกว่าของปลอม", "Barcelona 1992–95 ชุดเหย้า: ด้านหน้าไม่มีโลโก้ Kappa ดูป้าย \"Barça F.C.B.\" และ \"Sports Kappa S.A.\" ด้านใน"]'::jsonb,'["หมายเลขตรวจไม่เจอหรือขึ้นเสื้อตัวอื่น", "จุดบนป้ายกระจายไม่เท่ากัน", "ตัวอักษร Kappa ป่อง", "รูปคนสองคนใน Omini ผิดทรง", "ป้าย KOMBAT แบบตัวอักษรเจาะทะลุ"]'::jsonb,'เสื้อ Kappa ยุค 90 ถูกปลอมเยอะมาก','sourced','["https://footballshirtcollective.com/blogs/collectors-club/spot-fake-kappa"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('fb-demand-thai','apparel.football','genre','','เสื้อบอลวินเทจที่คนไทยตามหา','',ARRAY['manchester united','man utd','แมนยู','everton','ac milan','milan','man city','แมนซิตี้','real madrid','southampton','liverpool','ลิเวอร์พูล','sharp','batistuta','shevchenko','totti','gerrard','beckham','england 1990']::text[],'["นักเตะยุค 90–2000 ที่นิยม: Batistuta, Shevchenko, Totti, Gerrard, Le Tissier", "Everton และแมนยูยุคสปอนเซอร์ Sharp", "AC Milan ชุดเหย้าครบรอบ 100 ปี, แมนซิตี้ชุดเยือน 1993–94 (แฟน Oasis ตาม), เรอัลมาดริดยุค Beckham, อังกฤษฟุตบอลโลก 1990", "หายาก: Southampton 1991–93, แมนยูชุดเยือน 1970", "ราคาที่บทความระบุ: ส่วนใหญ่หลักร้อยถึงหลักพัน, AC Milan 100 ปี 8,000–10,000 บาท, แมนซิตี้เยือน 93–94 ตั้งแต่ 15,000 บาท, แมนยูเยือน 1970 หลักหมื่นขึ้นไป", "ร้านเฉพาะทาง: TJ Football Shop จตุจักร (อาคารตึกแดง)"]'::jsonb,'["ความร้อนทำให้เบอร์/ชื่อที่พิมพ์ละลาย เก็บในถุง ไม่ตากแดด", "การติดอาร์มแขนไม่ดีทำให้เสื้อเสียหาย"]'::jsonb,'ยุค 70–80 หายากที่สุด ทีม/ฤดูกาลที่ผูกกับนักเตะหรือเหตุการณ์ดังราคาดี ราคาในบทความอาจเปลี่ยนแล้ว','sourced','["https://themomentum.co/feature-football-jersey/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('fb-demand-global','apparel.football','trend','','เสื้อบอลย้อนยุคที่ฮิต (กระแส blokecore + ฟุตบอลโลก 2026)','',ARRAY['germany','nigeria','brazil','argentina','england','mexico','france','croatia','japan','canada','norway','world cup','blokecore','ทีมชาติ']::text[],'["ย้อนยุคที่ฮิต: เยอรมนี Italia 90, ไนจีเรีย 1994, บราซิล 2002, อาร์เจนตินา 1986, อังกฤษ Euro 96, เม็กซิโก 1998, ฝรั่งเศส 1998, โครเอเชีย 1998", "ชุดฟุตบอลโลก 2026 ที่ถูกพูดถึง: เยอรมนีเหย้า, เม็กซิโกเหย้า, ญี่ปุ่นเยือน, แคนาดาเยือนสีดำ, นอร์เวย์, อาร์เจนตินา", "กระแส blokecore ใส่เสื้อบอลคู่กับยีนส์ทรงหลวม"]'::jsonb,'["ชุดที่ฮิตคือชุดที่ถูกทำซ้ำ (retro remake) และปลอมมากที่สุด เช็ครหัสสินค้าเสมอ"]'::jsonb,'','sourced','["https://www.outlookindia.com/sports/football/fifa-world-cup-2026-hottest-jerseys-blokecore-retro-shirts-fashion-trends"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('fb-thailand','apparel.football','genre','','เสื้อทีมชาติไทย','',ARRAY['thailand','ทีมชาติไทย','ช้างศึก','ชบาแก้ว','grand sport','แกรนด์สปอร์ต','warrix','วอริกซ์']::text[],'["ผู้ผลิตที่ผ่านมา: Grand Sport และปัจจุบัน Warrix มีทั้งเกรดนักเตะและเกรดแฟน", "ที่นักสะสมสนใจ: Grand Sport ลาย \"ศักดิ์ศรีปฐพีไทย\" และเสื้อครบรอบ 100 ปี (2016–17) ที่บทความบอกว่าหายากแล้ว, รุ่น Limited Edition", "ราคาป้าย Warrix ฤดูกาล 2023/24: Player 2,490 บาท, Replica 890 บาท, เสื้อเชียร์ 399 บาท"]'::jsonb,'["เสื้อเชียร์ราคาถูกไม่ใช่เสื้อแข่ง อย่าตีราคาเท่ารุ่น Player"]'::jsonb,'','sourced','["https://www.ktc.co.th/article/lifestyle/sport/thailand-national-team-kits", "https://www.bangkokbiznews.com/lifestyle/1085512", "https://www.classicfootballshirts.co.uk/2016-17-thailand-100th-anniversary-shirt-xl-this16365185.html"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
